<template><div class="attribute-admin-page"><div class="page-head"><h2>Quản trị catalog</h2><a-space><a-input-search v-model:value="query" allow-clear placeholder="Tìm thuộc tính" style="width:240px" @search="load"/><a-button :loading="loading" @click="load"><ReloadOutlined/></a-button></a-space></div><a-tabs v-model:active-key="tab"><a-tab-pane key="definitions" tab="Thuộc tính mô tả"><a-table row-key="id" :columns="columns" :data-source="attributes" :loading="loading" :pagination="{pageSize:12}" :scroll="{x:900}"><template #bodyCell="{column,record}"><template v-if="column.key==='name'"><b>{{record.name}}</b><div class="muted">{{record.code}}</div></template><template v-else-if="column.key==='status'"><a-tag :color="record.status==='ACTIVE'?'green':'default'">{{record.status}}</a-tag></template><template v-else-if="column.key==='actions'"><a-space><a-button size="small" :disabled="record.verified" @click="verify(record)">Duyệt</a-button><a-button size="small" @click="openStandardize(record)">Chuẩn hóa</a-button><a-button size="small" danger :disabled="record.status==='INACTIVE'" @click="hide(record)">Ẩn</a-button></a-space></template></template></a-table></a-tab-pane><a-tab-pane key="axes" tab="Trục biến thể"><a-space style="margin-bottom:12px"><a-input v-model:value="axisQuery" placeholder="Tìm tên trục" @press-enter="loadAxes"/><a-button type="primary" @click="createAxis">Thêm gợi ý</a-button></a-space><a-table row-key="name" :columns="axisColumns" :data-source="axes" :loading="axisLoading"><template #bodyCell="{column,record}"><template v-if="column.key==='suggestions'"><a-space wrap><a-tag v-for="s in record.suggestions" :key="s.id" :color="s.verified?'green':'gold'">{{s.name}}<a-button v-if="!s.verified" type="link" size="small" @click="verifyAxis(s.id)">Duyệt</a-button></a-tag></a-space></template></template></a-table></a-tab-pane></a-tabs><a-modal v-model:open="standardizeOpen" title="Chuẩn hóa thuộc tính" ok-text="Lưu" :confirm-loading="saving" @ok="submitStandardize"><a-form layout="vertical"><a-form-item label="Tên chuẩn" required><a-input v-model:value="form.name"/></a-form-item><a-form-item label="Đơn vị mặc định"><a-input v-model:value="form.defaultUnit"/></a-form-item><a-form-item label="Danh mục"><a-select v-model:value="form.categoryIds" mode="multiple" :options="categoryOptions"/></a-form-item><a-form-item label="Lý do"><a-textarea v-model:value="form.reason"/></a-form-item></a-form></a-modal></div></template>
<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue';import{message}from'ant-design-vue';import{ReloadOutlined}from'@ant-design/icons-vue';import{GetListDanhMuc}from'@/services/api/permitall/sanpham/pmsanpham.api';import{getAdminProductAttributes,standardizeProductAttribute,hideProductAttribute,verifyProductAttribute,type AdminProductAttribute}from'@/services/api/admin/product-attribute.api';import{getAxisInsights,createAxisSuggestion,verifyAxisSuggestion,type AxisInsight}from'@/services/api/admin/variant-axis.api'
const tab=ref('definitions'),query=ref(''),loading=ref(false),saving=ref(false),attributes=ref<AdminProductAttribute[]>([]),selected=ref<AdminProductAttribute>(),standardizeOpen=ref(false),categoryOptions=ref<Array<{value:string;label:string}>>([]),form=reactive({name:'',defaultUnit:'',categoryIds:[] as string[],reason:''}),axisQuery=ref(''),axisLoading=ref(false),axes=ref<AxisInsight[]>([])
const columns=[{title:'Thuộc tính',key:'name',width:220},{title:'Kiểu',dataIndex:'dataType',width:130},{title:'Trạng thái',key:'status',width:120},{title:'Đã duyệt',dataIndex:'verified',width:90},{title:'Số sản phẩm',dataIndex:'productCount',width:110},{title:'Thao tác',key:'actions',fixed:'right',width:250}],axisColumns=[{title:'Tên trục',dataIndex:'name'},{title:'Số lần dùng',dataIndex:'usageCount'},{title:'Gợi ý chuẩn',key:'suggestions'}]
const load=async()=>{loading.value=true;try{attributes.value=await getAdminProductAttributes({q:query.value||undefined})}catch(e:any){message.error(e?.response?.data?.message||'Không tải được thuộc tính')}finally{loading.value=false}};const loadAxes=async()=>{axisLoading.value=true;try{axes.value=await getAxisInsights(axisQuery.value)}finally{axisLoading.value=false}};const verify=async(r:AdminProductAttribute)=>{await verifyProductAttribute(r.id);message.success('Đã duyệt');await load()};const hide=async(r:AdminProductAttribute)=>{await hideProductAttribute(r.id);message.success('Đã ẩn');await load()};const openStandardize=(r:AdminProductAttribute)=>{selected.value=r;Object.assign(form,{name:r.name,defaultUnit:r.defaultUnit||'',categoryIds:r.categoryIds||[],reason:''});standardizeOpen.value=true};const submitStandardize=async()=>{if(!selected.value||!form.name.trim())return;saving.value=true;try{await standardizeProductAttribute(selected.value.id,form);standardizeOpen.value=false;message.success('Đã chuẩn hóa');await load()}finally{saving.value=false}};const createAxis=async()=>{const name=window.prompt('Tên trục biến thể');if(name?.trim()){await createAxisSuggestion(name);await loadAxes()}};const verifyAxis=async(id:string)=>{await verifyAxisSuggestion(id);await loadAxes()};onMounted(async()=>{const c=await GetListDanhMuc();categoryOptions.value=(c.data||[]).map((x:any)=>({value:x.id,label:x.ten||x.name}));await load();await loadAxes()})
</script><style scoped>.attribute-admin-page{padding:20px}.page-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}.page-head h2{margin:0}.muted{color:#64748b;font-size:12px}</style>
